import{_ as i,o as a,c as r,a2 as t}from"./chunks/framework.CYjxsSA2.js";const g=JSON.parse('{"title":"漏洞测绘","description":"","frontmatter":{},"headers":[],"relativePath":"guide/webcrawl.md","filePath":"guide/webcrawl.md"}'),e={name:"guide/webcrawl.md"};function o(n,l,s,h,d,u){return a(),r("div",null,[...l[0]||(l[0]=[t('<h1 id="漏洞测绘" tabindex="-1">漏洞测绘 <a class="header-anchor" href="#漏洞测绘" aria-label="Permalink to &quot;漏洞测绘&quot;">​</a></h1><p>漏洞测绘对站点做深度分析：全站爬虫、指纹识别、敏感信息提取、目录探测、资产侦察，并可把值得深挖的站点直接交给军团。</p><h2 id="全站爬虫" tabindex="-1">全站爬虫 <a class="header-anchor" href="#全站爬虫" aria-label="Permalink to &quot;全站爬虫&quot;">​</a></h2><ul><li><strong>SPA 渲染</strong> —— 用浏览器加载动态内容，单页应用不再是盲区</li><li><strong>API 端点发现</strong> —— 从流量与前端代码中还原接口清单</li><li><strong>协议自动探测</strong> —— 只给 IP 或端口时，自动判断 <code>http</code> / <code>https</code> 再开爬</li><li><strong>手动 URL 爬取与批量导入</strong> —— 补充指定页面或整份 URL 清单</li><li><strong>资源树浏览</strong> —— 按页面 / JS 分类查看站点资源</li><li><strong>断点续扫</strong> —— 大批量任务中断后可继续</li></ul><h2 id="指纹识别" tabindex="-1">指纹识别 <a class="header-anchor" href="#指纹识别" aria-label="Permalink to &quot;指纹识别&quot;">​</a></h2><ul><li>内置指纹规则库，随包提供，无需额外配置</li><li>命中结果按重要程度分层排序：产品 → 技术栈 → 通用特征，站点图标命中优先</li><li>可按<strong>重要指纹</strong>或<strong>站点图标</strong>分组筛选（同图标站点往往同一套系统）</li></ul><h2 id="敏感信息提取" tabindex="-1">敏感信息提取 <a class="header-anchor" href="#敏感信息提取" aria-label="Permalink to &quot;敏感信息提取&quot;">​</a></h2><p>自动从页面与 JS 中识别并标记：</p><ul><li>Token、API Key、密码、JWT</li><li>云厂商 AK / SK 等凭据</li><li>内部 IP、内部域名、内网地址</li><li>身份证、手机号、邮箱等个人信息</li><li>SSRF 可疑参数、API 路径与前端路由</li></ul><p>结果汇总在<strong>敏感信息</strong>抽屉里，可按站点跳回详情。</p><h2 id="目录探测" tabindex="-1">目录探测 <a class="header-anchor" href="#目录探测" aria-label="Permalink to &quot;目录探测&quot;">​</a></h2><p>在测绘任务里对<strong>选中站点</strong>批量发起（工具条「更多 → 目录扫描」）：</p><ul><li>内置多套字典（短 / 中 / 长 / 后缀 / 敏感 API）</li><li>支持 GET / POST 两种方法</li><li>可选递归下钻</li><li>并发度可调，按目标承载能力设置</li><li>结果异步排队，完成后在站点详情里查看</li></ul><h2 id="资产侦察" tabindex="-1">资产侦察 <a class="header-anchor" href="#资产侦察" aria-label="Permalink to &quot;资产侦察&quot;">​</a></h2><p>对已完成测绘的站点单独下发一次<strong>侦察任务</strong>（工具条「资产侦察」，支持全部 / 选中）：</p><ul><li>产出面向资产画像的侦察报告，与渗透发现分开</li><li>可单独停止、单独下载报告，也可打开侦察会话看过程</li></ul><h2 id="智渗透" tabindex="-1">智渗透 <a class="header-anchor" href="#智渗透" aria-label="Permalink to &quot;智渗透&quot;">​</a></h2><p>选中站点后点<strong>智渗透</strong>，把站点作为目标交给军团：</p><ul><li>支持单站与批量，批量任务有独立进度与暂停 / 继续</li><li>已分析过的站点再下发会先停旧任务，避免两个会话抢同一目标</li><li>完成后可从站点行直接打开产生报告的那次会话</li></ul><h2 id="任务中心" tabindex="-1">任务中心 <a class="header-anchor" href="#任务中心" aria-label="Permalink to &quot;任务中心&quot;">​</a></h2><ul><li>任务以页签排列，显示完成进度，可重命名、可删除</li><li><strong>任务中心</strong>面板集中展示本项目全部任务的进度与状态</li><li>支持停止（选中 / 本任务 / 队列 / 全部）</li><li>目标可从文件批量导入，重复目标自动去重</li></ul><h2 id="联动" tabindex="-1">联动 <a class="header-anchor" href="#联动" aria-label="Permalink to &quot;联动&quot;">​</a></h2><ul><li><strong>与空间扫描联动</strong> —— 端口扫描发现 Web 服务后可直接触发测绘</li><li><strong>与军团联动</strong> —— 高价值站点交给军团深挖，军团也能自主下发测绘任务</li><li><strong>与漏洞管理联动</strong> —— 验证出的发现进入同一本漏洞账本</li></ul><h2 id="典型流程" tabindex="-1">典型流程 <a class="header-anchor" href="#典型流程" aria-label="Permalink to &quot;典型流程&quot;">​</a></h2><ol><li>从空间扫描结果选目标站点，或手动输入 URL</li><li>启动全站爬虫，观察资源树逐页展开</li><li>在指纹面板确认站点技术栈</li><li>对选中站点批量发起目录探测，发现隐藏入口</li><li>查看敏感信息抽屉，评估泄露面</li><li>把高价值站点「智渗透」给军团继续深入</li></ol>',25)])])}const b=i(e,[["render",o]]);export{g as __pageData,b as default};
